INSERT INTO `blog_posts` (`id`,`slug`,`slug_ar`,`slug_en`,`category_id`,`sort_order`,`is_published`,`show_on_home`,`image_url`,`image_alt_ar`,`image_alt_en`,`published_date`,`tag_ar`,`tag_en`,`title_ar`,`title_en`,`excerpt_ar`,`excerpt_en`,`body_ar`,`body_en`,`faq`,`schema_type`,`meta_title_ar`,`meta_title_en`,`meta_desc_ar`,`meta_desc_en`) VALUES ('fe9dba6c-4454-565e-883e-d57ad43de7bf','celebrating-ten-thousand-painless-births','الاحتفال-بعشرة-آلاف-حالة-من-الولادة-بدون-ألم','celebrating-ten-thousand-painless-births',NULL,907,1,0,'/images/الاحتفال-بعشرة-آلاف-حالة-من-الولادة-بدون-ألم/الاحتفال-بعشرة-آلاف-حالة-من-الولادة-بدون-ألم-1.jpg','الاحتفال بعشرة آلاف حالة من الولادة بدون ألم — د. أحمد مرزوق','Celebrating ten thousand Moms who enjoyed painless childbirth — Dr. Ahmed Marzouk',NULL,NULL,NULL,'الاحتفال بعشرة آلاف حالة من الولادة بدون ألم','Celebrating ten thousand Moms who enjoyed painless childbirth','24,مارس 2021','24,March 2021','<p>24,مارس 2021</p><p>تم الاحتفال ب10,000 أم استفادوا من الولادة بدون ألم مع الدكتور أحمد مرزوق، واستمر الاحتفال لمدة أسبوع، من 18 إلى 24 مارس ،2021 في داون تاون - التجمع الخامس- بجوار ستاربكس، وقد شمل الاحتفال عدة مفاجآت وتقديم خدمات مجانية والتقاط صور تذكارية.</p>','<p>24,March 2021</p><p>10,000 Moms who benefited from the painless childbirth were celebrated with Dr. Ahmed Marzouk. The celebration lasted for a week, from March 18 to March 24, 2021, in Fifth Settlement, next to Starbucks. The celebration included several surprises, free services, and taking souvenir photos.</p>',NULL,'BlogPosting','الاحتفال بعشرة آلاف حالة من الولادة بدون ألم | د. أحمد مرزوق','Celebrating ten thousand Moms who enjoyed painless childbirth | Dr. Ahmed Marzouk','Dr Ahmed Marzouk Clinic','Dr Ahmed Marzouk Clinic')
