INSERT INTO `blog_posts` (`id`,`slug`,`slug_ar`,`slug_en`,`category_id`,`sort_order`,`is_published`,`show_on_home`,`image_url`,`image_alt_ar`,`image_alt_en`,`published_date`,`tag_ar`,`tag_en`,`title_ar`,`title_en`,`excerpt_ar`,`excerpt_en`,`body_ar`,`body_en`,`faq`,`schema_type`,`meta_title_ar`,`meta_title_en`,`meta_desc_ar`,`meta_desc_en`) VALUES ('7f128106-d649-501d-8947-239229e63ade','opening-of-the-fifth-settlement-branch','افتتاح-فرع-التجمع-الخامس','opening-of-the-fifth-settlement-branch',NULL,910,1,0,'/images/افتتاح-فرع-التجمع-الخامس/افتتاح-فرع-التجمع-الخامس-1.jpg','dr ahmed marzouk — د. أحمد مرزوق','Opening of the Fifth Settlement Branch — Dr. Ahmed Marzouk',NULL,NULL,NULL,'افتتاح فرع التجمع الخامس','Opening of the Fifth Settlement Branch','07,يونيو 2017','07,June 2017','<p>07,يونيو 2017</p><p>تم بحمد الله افتتاح فرع التجمع الخامس، نظرًا للزحام الشديد وطول فترة الانتظار في فرع مدينة نصر، ولتسهيل الوصول لكل سكان التجمع ومدن القاهرة الجديدة. يُمكنكم الحجز مُسبقًا على رقم: 01063337333</p>','<p>07,June 2017</p><p>Dr. Ahmed Marzouk opened the Fifth Settlement branch clinic to solve the intense crowds and the long waiting duration in the Nasr City branch and to facilitate access to all residents of the settlements and New Cairo cities. You can make a reservation by calling 01063337333.</p>',NULL,'BlogPosting','افتتاح فرع التجمع الخامس | د. أحمد مرزوق','Opening of the Fifth Settlement Branch | Dr. Ahmed Marzouk','Dr Ahmed Marzouk Clinic','Dr Ahmed Marzouk Clinic')
