INSERT INTO `blog_posts` (`id`,`slug`,`slug_ar`,`slug_en`,`category_id`,`sort_order`,`is_published`,`show_on_home`,`image_url`,`image_alt_ar`,`image_alt_en`,`published_date`,`tag_ar`,`tag_en`,`title_ar`,`title_en`,`excerpt_ar`,`excerpt_en`,`body_ar`,`body_en`,`faq`,`schema_type`,`meta_title_ar`,`meta_title_en`,`meta_desc_ar`,`meta_desc_en`) VALUES ('0726bf7a-c819-5e37-bf9c-448af6e5238c','تجميد-البويضات','تجميد-البويضات',NULL,NULL,913,1,0,'/images/تجميد-البويضات/تجميد-البويضات-1.jpg','أضرار تجميد البويضات — د. أحمد مرزوق',NULL,NULL,NULL,NULL,'تجميد البويضات',NULL,'مع تأخر سن الزواج لدى الفتيات في الفترات الأخيرة أصبح لدى الكثير منهن مخاوف من عدم قدرتهن على الإنجاب، ومن هنا ظهرت تقنية تجميد البويضات كحل آمن لهذه المشكلة…',NULL,'<p>مع تأخر سن الزواج لدى الفتيات في الفترات الأخيرة أصبح لدى الكثير منهن مخاوف من عدم قدرتهن على الإنجاب، ومن هنا ظهرت تقنية تجميد البويضات كحل آمن لهذه المشكلة، حيث يتم فيه حفظ البويضات عن طريق سحبها من جسم المرأة وتجميدها لحين توافر الوقت المناسب للإنجاب.</p><p>ما هو السن الأنسب لتجميد البويضات؟ وما هي مدة الاحتفاظ بالبويضة المجمدة؟ يقل مخزون المبيض بعد بلوغ المرأة سن الخامسة والثلاثين، كما تقل جودة البويضات تدريجيًا حتى الوصول إلى مرحلة انقطاع الطمث، وتقل نسبة نجاح الحمل وتزداد فرص إنجاب طفل مصاب بعيوب خلقية، لذلك تلجأ الكثير من النساء إلى تجميد 10 بويضات أو أكثر قبل بلوغ هذا السن، وهناك نساء يلجأن لتجميد البويضات في سن الأربعين، ولكن يظل السن الأنسب هو من أواخر العشرينات حتى سن الخامسة والثلاثين لأن البويضات تكون محتفظة بجودتها، ويمكن احتفاظ بجودة البويضات حتى 10 سنوات بعد عملية التجميد.</p><p>متى تلجئين لتجميد البويضات؟</p><ul><li>إذا كنتِ تعانين من أمراض وراثية تؤثر على جودة البويضات أو تسبب لكِ العقم.</li><li>إذا كنتِ تعانين من أمراض المناعة الذاتية كالذئبة أو أمراض الدم كفقر الدم المنجلي.</li><li>إذا كنتِ مريضة سرطان وتتعرضين لعلاج كيميائي أو إشعاعي، قد يؤثر على قدرتكِ على الحمل في المستقبل.</li><li>إذا كنتِ تفكرين في تأجيل الزواج والحمل لما بعد الاربعين لأسباب دراسية أو اجتماعية.</li><li>إذا كنتِ ترغبين في الاحتفاظ بالبويضات الإضافية بعد عملية التلقيح الصناعي.</li></ul><p>كيف يتم تجميد البويضات؟ تنقسم عملية تجميد البويضات إلى عدة مراحل بدايةً من المرحلة التحضيرية ثم مرحلة تحفيز التبويض ثم سحب البويضات ثم تجميدها.</p><p>1. مرحلة التحضير لعملية تجميد البويضات يقوم الطبيب بعمل تحاليل للكشف عن وجود أي أمراض معدية كالتهاب الكبد والإيدز. تحاليل الكشف عن مستوى الهرمونات مثل مخزون المبيض AMH والهرمون المحفز للجريب FSH والاستراديول. الفحص باستخدام السونار لتقييم حالة المبيضين ومعرفة عدد البويضات الناضجة ومن الممكن أن يطلب إجراء تحليل مخزون البويضات أو تحليل مخزون المبيض.</p><p>2. مرحلة تحفيز التبويض بعد قراءة تحليل مخزون المبيض يُعطي الطبيب مجموعة من الأدوية لوقف الدورة الشهرية ثم علاجات هرمونية لتحفيز المبايض لإنتاج المزيد من البويضات، ثم يُجري فحوصات الدم ثم الفحص بالسونار لمتابعة عملية إنتاج البويضات.</p><p>3. مرحلة سحب البويضات يقوم الطبيب بسحب البويضات والتي يتراوح عددها بين الـ 5 و25 بويضة عن طريق إبرة صغيرة متصلة بمنظار الأشعة فوق الصوتية عن طريق المهبل، وتتم هذه العملية تحت تأثير التخدير باستخدام الحقن المسكنة للألم، تستمر العملية لمدة 20 دقيقة ثم تستطيع السيدة مغادرة المستشفى.</p><p>4. مرحلة تجميد البويضات بعد سحب البويضات يتم تجميدها في معمل الأجنة في درجة حرارة تحت الصفر لحين رغبة المرأة في الإنجاب.</p><p>كيف تُستخدم البويضات المجمدة لإتمام الحمل؟ تتم عملية إذابة البويضات المجمدة ثم تخصيبها بالحيوانات المنوية باستخدام التلقيح الصناعي ثم زراعتها في رحم الأم، بعد نجاح هذه العملية تظهر أعراض الحمل على المرأة ويلزمها الراحة التامة.</p><p>ما هي الأضرار المحتملة لعملية تجميد البويضات؟ قد تتسبب عملية تجميد البويضات في بعض الأضرار النادر حدوثها، منها ما يلي:</p><ul><li>من الممكن أن تتسبب إبرة البزل المستخدمة لاستخلاص البويضات في حدوث نزيف أو إصابة المرأة بعدوى.</li><li>الشعور بألم في المبيض نتيجة حقن العلاجات الهرمونية.</li><li>حدوث بعض المضاعفات البسيطة للتخدير المستخدم أثناء عملية سحب البويضات.</li><li>إمكانية حدوث بعض الآثار الجانبية الناتجة عن تنشيط المبايض مثل القيء، والغثيان، والإسهال، والانتفاخ وآلام البطن.</li><li>في حالة استخدام البويضات المجمدة للحمل في سن متأخر فإنه تزيد فرصة فشل الحمل والإجهاض.</li></ul><p>ما حكم تجميد البويضات وهل هو حلال؟ أباحت دار الإفتاء المصرية عملية تجميد البويضات إذا كان الهدف منها حفظ النسل فهي تعد من مكملات عملية طفل الأنابيب وقد أجازها العلماء بالضوابط التالية:</p><ul><li>يجب أن توضع البويضة المجمدة التي تم تخصيبها في رخم صاحبة البويضة فقط وألا يُسمح بوضعها في رحم سيدة أخرى.</li><li>يجب أن تُحفظ البويضة المجمدة في مكان آمن وألا تختلط مع بويضات أخرى لمنع اختلاط الأنساب.</li><li>يجب أن يكون الدافع لعمل عملية تجميد البويضات مشروعًا.</li><li>يجب أن تتم عملية تخصيب البويضة المجمدة بالحيوانات المنوية للزوج فقط وأن يكون الزواج قائمًا وقت التخصيب.</li></ul><p>كم هي تكلفة تجميد البويضات؟ تختلف التكلفة المطلوبة تبعًا إلى:</p><ul><li>التحاليل اللازمة لمتابعة عملية التبويض وللكشف عن الأمراض المعدية.</li><li>الأدوية المستخدمة لتحفيز المبايض، وكذلك سعر التحاليل الخاصة بالتبويض مثل سعر تحليل مخزون المبيض أو سعر تحليل مخزون البويضات.</li><li>عدد جلسات الموجات فوق الصوتية.</li><li>تكلفة تخزين البويضات في بنك البويضات وتقنية التجميد المستخدمة.</li></ul><p>هل تجميد البويضات عملية آمنة؟ تعد عملية تجميد البويضات عملية آمنة وليس لها علاقة بزيادة خطر تعرض الجنين لعيوب خلقية أو التشوهات، ولا تزيد بسببها مضاعفات الحمل مقارنةً بالحمل الطبيعي.</p><p>نسبة نجاح عملية تجميد البويضات وهل يحدث حمل مع ضعف مخزون المبيض؟ تعد نسبة نجاح عملية تجميد البويضات نسبة عالية ولكن تختلف نسبة نجاح عملية التلقيح الصناعي التي تُستخدم البويضات المجمدة وفقًا لعدة عوامل منها عمر المرأة، وحالة البويضة أثناء السحب وهل تم تجميدها بعد التخصيب أم قبله، وكذلك باختلاف النسبة الطبيعية لهرمون مخزون البويضات، فمخزون البويضات في سن الأربعين يخلتلف عن مخزونه في الثلاثين وكذلك في العشرين من العمر، وهل التنشيط يؤثر على مخزون البويضات أم لا وهكذا.</p><p>في النهاية إذا كنتِ تخافين من تقدمك في السن وتريدين المحافظة على فرصتك في الإنجاب عن طريق تجميد البويضات، فيمكنك التوجه إلى تقنية تجميد البويضات دون الخوف من فقدان فرصتكِ على الإنجاب على الإطلاق.</p>',NULL,NULL,'BlogPosting','تجميد البويضات | د. أحمد مرزوق',NULL,'Dr Ahmed Marzouk Clinic',NULL)
