INSERT INTO `blog_posts` (`id`,`slug`,`slug_ar`,`slug_en`,`category_id`,`sort_order`,`is_published`,`show_on_home`,`image_url`,`image_alt_ar`,`image_alt_en`,`published_date`,`tag_ar`,`tag_en`,`title_ar`,`title_en`,`excerpt_ar`,`excerpt_en`,`body_ar`,`body_en`,`faq`,`schema_type`,`meta_title_ar`,`meta_title_en`,`meta_desc_ar`,`meta_desc_en`) VALUES ('e178550c-d7c4-50cd-89c9-3655b4448a45','حقنة-الظهر-في-الولادة-القيصرية','حقنة-الظهر-في-الولادة-القيصرية',NULL,NULL,917,1,0,'/images/حقنة-الظهر-في-الولادة-القيصرية/حقنة-الظهر-في-الولادة-القيصرية-1.jpg','تجربتي مع إبرة الظهر للولادة القيصرية — د. أحمد مرزوق',NULL,NULL,NULL,NULL,'حقنة الظهر في الولادة القيصرية',NULL,'يظل الألم أحد المخاوف الرئيسية التي تعاني منها النساء في عملية الولادة القيصرية إلى جانب خوفهم من التخدير الكلي ومضاعفاته فظهرت الولادة القيصرية بدون ألم باس…',NULL,'<p>يظل الألم أحد المخاوف الرئيسية التي تعاني منها النساء في عملية الولادة القيصرية إلى جانب خوفهم من التخدير الكلي ومضاعفاته فظهرت الولادة القيصرية بدون ألم باستخدام حقنة الظهر، والتي تعد أحد أنواع التخدير النصفي، حيث تبقى الأم واعية خلال مراحل الولادة القيصرية لكنها لا تشعر بالألم، إلى جانب مساهمتها في تقليل نسبة وصول أدوية التخدير إلى الجنين، ويتم حقنها أسفل الظهر فتسبب فقدان الإحساس في المنطقة حول البطن ومنطقة الحوض بالكامل.</p><p>كما يوجد أكثر من نوع  من حقنة الظهر، منها حقنة الإبيديورال (تخدير فوق الجافية) وحقنة السباينال (تخدير سائل الحبل الشوكي).</p><p>وتتسائل الكثير من السيدات عن ما هي حقنة الظهر للولادة الطبيعية؟ وعن إبرة الظهر للولادة الطبيعية فوائدها وأضرارها، إذ تُستخدم إبرة الظهر في الولادة الطبيعية (الإبيديورال ) لتخفيف ألم المخاض، فقد حققت تجارب حقنة الإبيديورال نجاحًا كبيرًا في تخفيف ألم الولادة الطبيعية في حالة خوف السيدة من الألم حيث تسكِّن الألم في النصف السفلي مع الاحتفاظ بقدرة الأم على الدفع للمساعدة في الولادة، أما في حالات الولادة القيصرية فيستخدم سباينال أو إيبيدورال.</p><p>هل إبرة الظهر نفس البنج النصفي؟</p><ul><li>يعد البنج النصفي فعالًا أسرع من إبرة الظهر لأن المخدر يدخل مباشرةً إلى الحبل الشوكي ويبدأ فعاليته في خلال 5 دقائق ولا يستدعي بقاء الحقنة بالجسم كإبرة الظهر.</li><li>تسكِّن إبرة الظهر النصف السفلي من جسم المرأة مع الاحتفاظ بقدرتها على الدفع في حالة الولادة الطبيعية، أما البنج النصفي فإنه يخدر العضلات ولا تستطيع المرأة الدفع للمساعدة في الولادة الطبيعية، لذلك لا يُستخدم البنج النصفي في الولادة الطبيعية.</li><li>لا يُستخدم البنج النصفي في حالات أمراض القلب وأمراض الجهاز التنفسي.</li></ul><p>كيف تؤخذ إبرة الظهر للولادة؟</p><ul><li>يطلب منكِ طبيب التخدير الجلوس أو الاستلقاء على جانبك.</li><li>يقوم بتعقيم منطقة الظهر وحقن مخدر موضعي لتخفيف ألم إدخال إبرة الظهر.</li><li>يقوم الطبيب بإدخال إبرة مجوفة بين الفقرات ثم يمرر أنبوب القسطرة عبر الإبرة.</li><li>يتم إخراج الإبرة وتثبيت أنبوب القسطرة على الظهر.</li><li>تُستخدم القسطرة لتعبئة الأدوية لتخفيف الألم.</li><li>يراقب الطبيب ضغط الدم والأكسجين، ونبضات قلب الأم والجنين.</li><li>ينتهي مفعول حقنة الظهر بعد عدة ساعات من إزالة القسطرة.</li><li>يفضل الطبيب قيام المريضة بالمشي داخل الغرفة لإزالة تنميل الساقين.</li></ul><p>نصائح هامة قبل إعطاء حقنة الظهر في الولادة القيصرية:</p><ul><li>الالتزام بتعليمات دكتور أحمد مرزوق الخاصة بمواعيد التوقف عن تناول الطعام والشراب.</li><li>أن يقوم بإعطاء الحقنة طبيب تخدير متمرس.</li></ul><p>متى تؤخذ ابرة الظهر للولادة؟ تؤخذ ابرة الظهر عند بدابة آلام الطلق، أو بعد حدوث توسع عند عنق الرحم بمقدار 3 سم.</p><p>ما هي موانع استخدام حقنة الظهر في الولادة القيصرية؟</p><ul><li>رفض السيدة إبرة الولادة بدون ألم.</li><li>معاناة السيدة من سيولة الدم، أو ارتفاع ضغط الدماغ، أو أورام في الدماغ، أومشاكل في فقرات الظهر.</li><li>التهاب أو عدوى جلدية في مكان حقنة الظهر.</li><li>في حالات فقد الدم السابق نتيجة للنزيف.</li><li>المعاناة من ضغط الدم المنخفض.</li><li>وجود حساسية لأي من مكونات الحقنة.</li><li>في الحالات التي تعاني من تسمم الحمل.</li></ul><p>حقنة بدون ألم للولادة القيصرية فوائدها وأضرارها؟ توفر إبرة الظهر العديد من المميزات منها:</p><ul><li>تجنُّب  مخاطر التخدير الكلّي في العمليات القيصرية والذي يشكِّل خطورة في بعض الحالات مثل، أمراض القلب والجهاز التنفسي.</li><li>عدم الحاجة إلى التنفس الصناعي.</li><li>تحد من الألم بصورة أفضل من المسكنات التي تعطى في حالة التخدير الكلي.</li><li>تستعيد السيدة حركة الأمعاء والقدرة على تناول الطعام والشراب بصورة أسرع وأفضل من التخدير الكلي.</li><li>تقلل نسبة وصول أدوية التخدير إلى الجنين بالمقارنة بالتخدير الكلي.</li><li>تزيد من ارتباط الأم بالمولود حيث تبقى واعية وتعيش مراحل الولادة كاملة.</li></ul><p>على الرغم من فوائد حقنة الظهر في العمليات القيصرية إلا أن لها بعض الأضرار غير شائعة الحدوث وإن حدثت فهي سريعة الزوال، منها: انخفاض ضغط الدم: قد تُصاب قلة من السيدات بانخفاض ضغط الدم، لذا يتم مراقبة ضغط الدم أثناء العملية حتى لا يؤثر ذلك على استمرارية تدفق الدم للجنين. الحكة: قد تعاني بعض السيدات من الحكة أو التهيج البسيط في الجلد نتيجة الأدوية المخدرة، وللتغلب على ذلك يعطيها الطبيب الأدوية المضادة للحكة. الصداع: من الممكن أن تعاني بعض السيدات من الصداع بعد إبرة الظهر فيصف لها الطبيب الأدوية الخاصة بالصداع وينصح بشرب الكافيين باعتدال وتناول كميات وفيرة من المياه. ارتفاع درجة الحرارة: قد تعاني بعض السيدات من ارتفاع درجات الحرارة. ألم الظهر: قد تعاني بعض السيدات من آلام الظهر مكان إبرة الولادة بدون ألم. تنميل الساقين: ينصح الطبيب بالمشي لزوال التنميل.</p><p>سعر إبرة الظهر للولادة: يختلف سعر ابرة الظهر للولادة الطبيعية وكذلك للولادة القيصرية نتيجة عدة عوامل منها خبرة الطبيب في العمليات القيصرية وخبرة طبيب التخدير، وكذلك خبرة الفريق المعاون للطبيب وجودة المستشفى التي ستتم فيها العملية والأدوية المستخدمة والمتابعة بعد العملية.</p><p>تجربتي مع إبرة الظهر للولادة القيصرية: تحكي إحدى السيدات تجربتها في الولادة القيصرية بدون ألم مع الدكتور أحمد مرزوق باستخدام إبرة الظهر، حيث كانت تخاف من الشعور بألم وقت إدخال الحقنة في الظهر وهو ما لم يحدث مع الدكتور أحمد مرزوق ولم تشعر بأي ألم أثناء العملية على الإطلاق، وتنصح أي سيدة ترغب في الولادة القيصرية بدون ألم التوجه للدكتور أحمد مرزوق والذي تعتبره الأفضل في جراحات النساء والولادة.</p>',NULL,NULL,'BlogPosting','حقنة الظهر في الولادة القيصرية | د. أحمد مرزوق',NULL,'Dr Ahmed Marzouk Clinic',NULL)
