INSERT INTO `blog_posts` (`id`,`slug`,`slug_ar`,`slug_en`,`category_id`,`sort_order`,`is_published`,`show_on_home`,`image_url`,`image_alt_ar`,`image_alt_en`,`published_date`,`tag_ar`,`tag_en`,`title_ar`,`title_en`,`excerpt_ar`,`excerpt_en`,`body_ar`,`body_en`,`faq`,`schema_type`,`meta_title_ar`,`meta_title_en`,`meta_desc_ar`,`meta_desc_en`) VALUES ('c8212000-f67e-5e44-a6f9-d1c4df08b9d0','علاج-التهابات-المهبل','علاج-التهابات-المهبل',NULL,NULL,919,1,0,'/images/علاج-التهابات-المهبل/علاج-التهابات-المهبل-1.jpg','علاج التهابات المهبل — د. أحمد مرزوق',NULL,NULL,NULL,NULL,'علاج التهاب المهبل',NULL,'تنتشر التهابات المهبل بين عدد كبير من النساء وتختلف في أعراضها من سيدة لأخرى، وتختلف في أعراضها كالحكة والحرقة، والأضرار التي تسببها كتأخر حدوث الحمل',NULL,'<p>تنتشر الالتهابات المهبلية بين عدد كبير من النساء وتختلف في أعراضها من سيدة لأخرى، وتختلف في أعراضها كالحكة والحرقة، والأضرار التي تسببها كتأخر حدوث الحمل والمضاعفات الصحية للحامل وجنينها، لذا يجب الاهتمام بعلاج الالتهابات المهبلية وزيادة الوعي بكيفية تجنبها، تابع معنا المقال التالي مع الدكتور أحمد مرزوق لتعرف أكثر.</p><h2>يختلف علاج التهاب المهبل وفقا للمسببات الالتهاب نفسه، وهل حدث الالتهاب بسبب البكتيريا أو الفطريات أو نتيجة للعادات الخاطئة:</h2><h3>1. التهاب المهبل البكتيري:</h3><p>يمكن أن تُصاب المرأة بعدوى بكتيرية في منطقة المهبل نتيجة حدوث اضطراب في توازن البكتيريا النافعة المتواجدة في منطقة المهبل، نتيجة تغيير بعض الهرمونات أو إصابتها بتلك العدوى من زوجها. ويتميز الالتهاب البكتيري بالأعراض التالية:</p><ul><li>إفرازات رمادية اللون.</li><li>احمرار المهبل.</li><li>الشعور بحرقان في المهبل.</li><li>ألم عند التبول.</li></ul><p>ويتم علاج الالتهاب البكتيري من خلال تناول أدوية عن طريق الفم: كأقراص ميترونيدازول (Flagyl) أو كليندامايسين، وأدوية موضعية: مثل كريم كليندامايسين الذي يُدهن على المهبل أو جل ميترونيدازول (MetroGel)، أو من خلال وصف كبسولات تُوضَع داخل المهبل.</p><h3>2. التهاب المهبل الفطري:</h3><p>يحدث نتيجة تغير في درجة حموضة منطقة المهبل بسبب التغيرات الهرمونية، وتزداد فرص حدوثه نتيجة كثرة تناول المضادات الحيوية أو الإصابة بالسكري. وتستطيعين تمييز أعراضه التي تحدث من خلال:</p><ul><li>حكة في المهبل.</li><li>ظهور إفرازات بيضاء سميكة تُشبه الجبن.</li><li>الشعور بحرقان في المهبل.</li><li>وجود ألم عند الجماع.</li></ul><p>ويتم علاج الالتهاب الفطري من خلال بعض الأدوية عن طريق الفم كأقراص فلوكونازول أو كريم كلُوتريمازول أو مِيكُونازُول .</p><h3>3. داء المشعرات:</h3><p>ينتج نتيجة إصابة المرأة  بأحد أنواع الطفيليات، وينتقل عن طريق ممارسة الجنس. ومن أهم أعراضه:</p><ul><li>الإفرازات الصفراء أو الخضراء كريهة الرائحة جدًا.</li><li>حكة شديدة.</li><li>حرقان عند التبول.</li><li>الشعور بالألم أثناء الجماع.</li></ul><p>ويتم علاج داء المشعرات من خلال تناول أقراص ميترونيدازول (Flagyl).</p><h3>4. التهاب المهبل الضموري:</h3><p>هو أحد أنواع  التهابات المهبل الذي يحدث بعد انقطاع الطمث نتيجة انخفاض مستوى الإستروجين، ويمكن علاج التهاب المهبل الضموري من خلال أخذ أدوية تحتوي على هرمون الاستروجين التعويضي.</p><p>ونظرا للمشكلات التي يسببها التهاب المهبل للنساء وخاصة الحوامل منهم فسوف نستعرض معكِ أهم أسباب وعوامل الخطر التي تزيد من فرصة إصابتك بالتهاب المهبل.</p><h2>أسباب حدوث عدوى في المهبل:</h2><p>يوجد الكثير من مسببات التهاب المهبل مثل التالي:</p><ul><li>اختلال الاتّزان السّليم للبكتيريا داخل المَهْبِل.</li><li>تلوث خارجي سواء كان بكتيري أو فطري.</li><li>انخفاض نسبة هرمون الإستروجين في مرحلة اليأس.</li><li>الأمراض المنقولة جنسيًا.</li><li>كثرة استخدام المضادات الحيوية.</li><li>الإصابة بمرض السكر.</li><li>تغيير الهرمونات خاصة أثناء فترة الحمل.</li><li>استخدام وسائل منع الحمل كاللولب.</li><li>غزارة الدورة الشهرية.</li></ul><h2>إذا كنتِ مصابة بالتهاب المهبل فكيف سيتم تشخيصك؟</h2><p>1. من خلال معرفة التاريخ الطبي للمريضة وإذا عانيت سابقًا من أي أمراض منقولة جنسيًا. 2. من خلال فحص الحوض ومعرفة درجة حموضة المهبل: إذ يُساعد فحص المهبل على معرفة أسباب  الإفرازات وتشير الحموضة العالية إلى إمكانية الإصابة بداء المشعرات، أو الإصابة بالالتهاب البكتيري. 3. أخذ عينة من إفرازات المهبل: إذ يساعد تحليل الإفرازات المهبلية في الكشف عن سببها وعلاجها.</p><h2>كيف تقي نفسكِ من الإصابة بالتهاب المهبل؟</h2><p>1- المسح دائمًا من الأمام إلى الخلف بعد الذهاب إلى الحمام. 2- الامتناع عن غسل المهبل بالصابون واستخدام الغسول الخاص أو الماء فقط. 3- عدم استخدام الدّش المهبلي لأنه يُغير توازن الجراثيم المتواجدة بصورة طبيعية في المهبل. 4- استخدام الواقي الذكري عند العلاقة الزوجية. 5- غسل اليدين جيدًا وبصورة منتظمة.﻿ 6- الإقلاع عن التدخين. ﻿﻿ 7- ارتداء الملابس الداخلية القطنية والابتعاد عن السراويل الضيقة. 8- تغيير الملابس الداخلية أكثر من مرة يوميًا. 9- عدم استخدام الفوط الصحية المعطرة. 10- عدم استخدام حمامات السباحة الغير مطهرة. 11- تناول الزبادي واللبن الرائب لدورها في الحفاظ على التوازن البكتيري للمهبل. 12- ضبط مستوى السكر في الدم.</p><h2>هل تستطيعين ممارسة علاقتك الحميمية مع الشريك في حالة إصابتك بالتهاب المهبل؟</h2><p>إن كنت مصابة بالتهاب المهبل النشط وتشعرين بحدة الأعراض فإن ممارسة العلاقة الحميمية قد تسبب لكِ الإزعاج وقد تزيد من حدة الأعراض، وإذا كان التهاب المهبل ناتج عن داء المشعرات الذي ينتقل جنسيًا فمن المحتمل أن تنقلي العدوى لشريكك. أما إذا أكد الطبيب لك أنك مصابة بعدوى فطرية مزمنة وليس لديك أعراض حادة ومزعجة، فيمكنك ممارسة العلاقة الحميمية دون قلق من تفاقم الأعراض طالما لا تنزعجين عند القيام بها، مع الاهتمام بالنظافة الشخصية بعد الجماع واستخدام الغسول المطهر الخاص بكِ.</p><h2>التهاب المهبل والحمل:</h2><p>ينشط التهاب المهبل لدى السيدة الحامل نتيجة للتغيُّر الكبير في هرمونات الجسم مما يسبب لها الإزعاج والحكة، ولكن لا يتوقف تأثير الإصابة بالتهاب المهبل على ذلك فهو يُسبب الكثير من الأضرار في حالة تركه دون علاج مثل:</p><ul><li>إمكانية حدوث ولادة مبكرة.﻿</li><li>احتمالية التعرض للإجهاض.﻿</li><li>انخفاض وزن المولود عند الولادة.</li><li>التهاب المشيمة.</li><li>التهاب بطانة الرحم بعد الولادة القيصرية.</li><li>وفاة الجنين.</li><li>يؤثر عدم علاج التهاب المهبل بصورة سلبية على السيدة التي ترغب في الحمل؛ لأنه يسبب تغيير في حموضة المهبل مما يؤثر على الحيوانات المنوية وإمكانية حدوث الإخصاب.</li></ul><h2>علاج التهاب المهبل لدى الحامل:</h2><p>يفضل الطبيب في حالة إصابة الحامل بالتهاب المهبل استخدام الغسول والعلاجات الموضعية مثل الكريمات واللبوس المهبلى؛ لتجنب تأثير بعض الأدوية التي تتناول عن طريق الفم على الجنين خاصةً في الفترة الأولى من الحمل.</p>',NULL,NULL,'BlogPosting','علاج التهاب المهبل | د. أحمد مرزوق',NULL,'تنتشر التهابات المهبل بين عدد كبير من النساء وتختلف في أعراضها من سيدة لأخرى، وتختلف في أعراضها كالحكة والحرقة، والأضرار التي تسببها كتأخر حدوث الحمل',NULL)
