INSERT INTO `blog_posts` (`id`,`slug`,`slug_ar`,`slug_en`,`category_id`,`sort_order`,`is_published`,`show_on_home`,`image_url`,`image_alt_ar`,`image_alt_en`,`published_date`,`tag_ar`,`tag_en`,`title_ar`,`title_en`,`excerpt_ar`,`excerpt_en`,`body_ar`,`body_en`,`faq`,`schema_type`,`meta_title_ar`,`meta_title_en`,`meta_desc_ar`,`meta_desc_en`) VALUES ('7fc1a2bb-332b-52d5-af31-5ee435c390c9','تكيس-المبايض','تكيس-المبايض',NULL,NULL,922,1,0,'/images/تكيس-المبايض/تكيس-المبايض-1.jpg','هل يحدث تبويض مع تكيس المبايض — د. أحمد مرزوق',NULL,NULL,NULL,NULL,'تكيس المبايض',NULL,'تعتبر حالة تكيس المبايض حالة شائعة بين الكثير من النساء بعد سن البلوغ، وتحدث نتيجة لاضطراب في الهرمونات التناسلية التي تنتجها المرأة فيحدث زيادة في إنتاج هرمون',NULL,'<p>تعتبر حالة تكيس المبايض حالة شائعة بين الكثير من النساء بعد سن البلوغ، وتحدث نتيجة لاضطراب في الهرمونات التناسلية التي تنتجها المرأة فيحدث زيادة في إنتاج هرمون الذكورة (الأندروجين)، مما يؤثر على وظيفة المبيض في إنتاج البويضات (فقد لا تنمو البويضة بالصورة الطبيعية أو قد لا يتم إطلاقها من المبيض على الإطلاق) مما يسبب حدوث خلل في الدورة الشهرية لدى المرأة، ويُعرف تكيس المبايض بأنها حالة تظهر فيها حويصلات رقيقة مليئة بالسوائل على المبيض نفسه وهو ما يظهر شكل التكيُّس.</p><h2>متى من الممكن أن أشك في إصابتي بتكيس المبايض؟</h2><p>إذا ظهر لديك أي مما يلي:</p><p>ظهور شعر زائد على الجسم، ويُصبح شعر الوجه أكثر سمكًا وغامق في لونه، كما يزيد نمو الشعر في الجسم عن الطبيعي.</p><ul><li>السمنة وخاصةً في منطقة الخصر مع إيجاد صعوبة في خسارة الوزن.</li><li>اضطراب الدورة الشهرية والذي يتمثل في غزارة الدورة الشهرية أو انقطاعها أو طول الفترة بين الدورتين كل شهر.</li><li>ظهور حب الشباب.</li><li>ظهور الشواك الأسود (جلد سميك وداكن في منطقة الرقبة وتحت الإبط ).</li><li>وجود ألم في منطقة الحوض.</li><li>عدم انتظام التبويض.</li><li>العقم.</li><li>ارتفاع مقاومة الأنسولين.</li><li>القلق واضطراب النوم.</li><li>الاكتئاب .</li><li>اضطرابات الطعام.</li><li>الإرهاق والتعب.</li><li>تساقط الشعر.</li></ul><h2>ما هي الأسباب التي تؤدي إلى الإصابة بتكيس المبايض؟</h2><h3>العوامل الوراثية:</h3><p>على الرغم من عدم وجود جين محدد مسئول عن تكيس المبايض إلا أنه يوجد مجموعة من الجينات التي تلعب دورًا في انتقال هذا المرض، فقد وجدت الدراسات أن حوال 25% من النساء اللاتي يعانين من هذا المرض كانت أمهاتهم مصابة به، وأن مايقرب من 30% من النساء المصابة به كانت لديهم أخوات مصابات أيضًا.</p><h3>مقاومة الأنسولين:</h3><p>وهي حالة تقل فيها حساسية خلايا الجسم للأنسولين، فيحاول الجسم تعويض ذلك بإفرازه للمزيد من الأنسولين مما يسبِّب زيادة الأنسولين في الجسم، مما يؤدي إلى إفراز المبيض للمزيد من هرمون الأندروجين (مجموعة من الهرمونات الذكورية) وظهور أعراض تكيس المبايض.</p><h3>الاضطرابات الهرمونية:</h3><p>تُعاني الكثير من المصابات بتكيس المبايض من الاضطرابات الهرمونية كزيادة في هرمونات الذكورة وبالأخص ارتفاع هرمون التستوستيرون، وارتفاع كلًا من البرولاكتين وهرمون الجسم الأصفر، وانخفاض في الجلوبيولين المرتبط بالهرمونات الجنسية، وتظهر هذه الاضطرابات نتيجة لحدوث قصور في المبيض نفسه أو نتيجة حدوث خلل في الغدد المسؤولة عن إفراز تلك الهرمونات.</p><h3>الالتهاب البسيط:</h3><p>نتيجة ارتفاع في خلايا الدم البيضاء المسؤولة عن مهاجمة العدوى، مما يؤدي لزيادة إفراز الأندروجين من المبيض.</p><h2>من هم الأشخاص الأكثر عرضة للإصابة بتكيس المبايض؟</h2><ul><li>من تعاني من السمنة ومقاومة الأنسولين.</li><li>النساء اللاتي لديهن تاريخ عائلي للمرض.</li><li>مرضى سكر الدم من النوع الثاني.</li><li>النساء اللاتي يعانين من التهاب الحوض.</li><li>أصحاب مرض الانتباذ الرحمي.</li></ul><h2>عوامل تساعدك على التنبؤ بوجود تكيس المبايض:</h2><ul><li>معرفة التاريخ الطبي للمريضة والأعراض التي تعاني منها.</li><li>إجراء تحاليل لفحص نسبة هرمونات الأنسولين، والتستوستيرون، والبرولاكتين، وهرمون الجسم الأصفر، والجلوبيولين المرتبط بالهرمونات الجنسية.</li><li>الكشف عن مؤشر كتلة الجسم، ووجود الشواك الأسود لديكِ، وارتفاع معدل الشعر الزائد في الجسم، وارتفاع ضغط الدم.</li><li>التصوير بالموجات فوق الصوتية لمنطقة الحوض للكشف عن تكيس المبايض.</li></ul><h2>كيفية يمكن علاج تكيس المبايض مع الدكتور أحمد مرزوق؟</h2><p>يتوقف علاج تكيس المبايض على مجموعة من العوامل مثل:</p><ul><li>عمر المريضة.</li><li>الصحة العامة للمريضة.</li><li>مدى شدة الأعراض.</li><li>الرغبة في حدوث حمل في المستقبل.</li></ul><p>وتتنوع خطط العلاج بين تغيير نمط الحياة في البداية ثم تناول الأدوية والتدخل الجراحي:</p><p>تغيير نمط الحياة: يمكنكِ تغيير نمط الحياة والالتزام بنظام غذائي صحي لتقليل مقاومة الأنسولين وخفض الوزن، وممارسة بعض التمارين الرياضية.</p><p>العلاج بالأدوية:</p><ul><li>من خلال تناول حبوب منع الحمل: وهي تُستخدم في حالة عدم رغبة المريضة في الحمل، وتساعد في التحكم في دورات الطمث، وخفض مستويات الأندروجين.</li><li>من خلال تناول أدوية السكر: وهي تُستخدم لتقليل مقاومة الأنسولين وتقليل مستويات هرمون الأندروجين.</li><li>من خلال أدوية تحفيز الإباضة لمن ترغب في الحمل والتي تعمل على زيادة معدل التبويض.</li><li>من خلال أدوية لوقف تساقط الشعر.</li><li>لعلاج الاكتئاب واضطرابات النوم.</li><li>إزالة الشعر الزائد باستخدام تقنية الليزر.</li></ul><p>العلاج باستخدام التدخل الجراحي: وهو عبارة عن إجراء جراحي بسيط يتم باستخدام المنظار الطبي يتم به عمل كي للمبيض لعلاج مشاكل الخصوبة.</p><h2>مضاعفات تكيس المبايض:</h2><p>في حالة عدم علاج تكيس المبايض فإنه يزيد من فرص الإصابة بالأمراض التالية:</p><ul><li>أمراض القلب.</li><li>ارتفاع ضغط الدم.</li><li>السكري من النوع الثاني.</li><li>ارتفاع الكوليسترول.</li></ul><h2>الحمل وتكيس المبايض:</h2><p>تصبح الحامل المصابة بالسمنة وتكيس المبايض أكثر عرضةً للإصابة بسكر الحمل وارتفاع ضغط الدم بعد الحمل، لذا عليكِ باتباع النصائح التالية:</p><ul><li>الحفاظ على مستوى السكر الطبيعي قبل الحمل.</li><li>التمتع بوزن صحي ومؤشر كتلة جسم بين 18.5 و 25 قبل الحمل.</li><li>الحد من شرب الكافيين.</li><li>تناول المكملات الغذائية كحمض الفوليك.</li></ul><h2>كيف تحمي نفسكِ من الإصابة بتكيس المبايض؟</h2><ul><li>المحافظة على وزن صحي ومؤشر كتلة جسم لا يتعدى 25.</li><li>تناول وجبات صحية تحتوي على الخضروات والفواكه والألياف، والابتعاد عن النشويات كالخبز الأبيض والدقيق الأبيض لتجنب مقاومة الأنسولين.</li><li>الابتعاد عن الضغط العصبي.</li><li>المحافظة على نسبة السكر في الدم وتناول أدوية السكر بانتظام خاصةً إذا كنتِ مريضة سكر.</li><li>ممارسة الرياضة بانتظام للحفاظ على وزنكِ الصحي وتحسين حالتكِ النفسية.</li></ul>',NULL,NULL,'BlogPosting','تكيس المبايض | د. أحمد مرزوق',NULL,'تعتبر حالة تكيس المبايض حالة شائعة بين الكثير من النساء بعد سن البلوغ، وتحدث نتيجة لاضطراب في الهرمونات التناسلية التي تنتجها المرأة فيحدث زيادة في إنتاج هرمون ',NULL)
