INSERT INTO `blog_posts` (`id`,`slug`,`slug_ar`,`slug_en`,`category_id`,`sort_order`,`is_published`,`show_on_home`,`image_url`,`image_alt_ar`,`image_alt_en`,`published_date`,`tag_ar`,`tag_en`,`title_ar`,`title_en`,`excerpt_ar`,`excerpt_en`,`body_ar`,`body_en`,`faq`,`schema_type`,`meta_title_ar`,`meta_title_en`,`meta_desc_ar`,`meta_desc_en`) VALUES ('941791c1-7956-51c9-ad73-a8ce1acf60d1','الولادة-بدون-ألم-تاب-لوك','الولادة-بدون-ألم-تاب-لوك',NULL,NULL,928,1,0,'/images/الولادة-بدون-ألم-تاب-لوك/الولادة-بدون-ألم-تاب-لوك-1.jpg','تجربتي مع التاب بلوك — د. أحمد مرزوق',NULL,NULL,NULL,NULL,'الولادة بدون ألم تاب بلوك',NULL,'الولادة القيصرية بدون ألم هي أمنية عزيزة لكل أم تحلم بتحقيق حلم الأمومة وحمل مولودها بين يديها، لكنها تخاف من آلام الولادة، ولكن السيدات اللاتي وقع اختيارهن …',NULL,'<p>الولادة القيصرية بدون ألم هي أمنية عزيزة لكل أم تحلم بتحقيق حلم الأمومة وحمل مولودها بين يديها، لكنها تخاف من آلام الولادة، ولكن السيدات اللاتي وقع اختيارهن على دكتور أحمد مرزوق استشاري جراحات النساء والتوليد استطعن تحقيق هذه الأمنية، حيث يستخدم دكتور أحمد مرزوق حقنة الولادة بدون ألم تاب بلوك ليجعل السيدة لا تشعر بآلام الولادة القيصرية.</p><p>ما هي الولادة بدون ألم؟ هي الولادة التي يحاول بها الطبيب الجراح أن يخفف من ألم فتح البطن ومن وجع الفتح الجراحي بعد عملية الولادة، من خلال التقنيات الطبية الحديثة، ومن أشهر تلك الوسائل التي تساعد على المرور بولادة بدون ألم هي جهاز تاب بلوك وجهاز الـ PCA.</p><p>تجربتي مع التاب بلوك مركز دكتور أحمد مرزوق: تحكي إيمان تجربتها قائلة (عمري ما تخيلت إن القيصرية تبقى سهلة كدة ومن غير ألم تقريبًا في منطقة الجرح، دكتور أحمد مش بس دكتور نساء شاطر، لأ وكمان أخصائي نفسي ممتاز بيهتم بحالة المريضة النفسية ويتابعها ويطمئن عليها بعد العملية، ومبسوطة بتجربتي مع الولادة القيصرية بدون ألم معاه جدًا).</p><p>ما هو تاب بلوك حقنة الولادة القيصرية بدون ألم؟ في حالة خضوع الأم للولادة القيصرية نتيجةً لحالتها الصحية أو بسبب وضعية الجنين، فإنها تُعاني من الألم بعد الولادة بسبب الجرح أسفل البطن بعد زوال تأثير التخدير، ولكن يوفر الدكتور أحمد مرزوق تقنية تاب بلوك للولادة بدون ألم، وهي تقنية يتم فيها تخدير جدار البطن عن طريق تاب بلوك (TAP Block) والذي يتم فيه تخدير العصب المُغذي لمنطقة البطن والذي يقع فيها الجرح مما يوقف إشارات الألم الصادرة من هذه المنطقة فلا تصل إلى المخ، فتستطيع السيدة التحرك بعد العملية دون الشعور بألم الجرح لمدة تصل إلى 24 ساعة أو أكثر، كما أنها تقلل كثيرًا من الشعور بألم الجرح لعدة أيام بعد العملية، إذ تعمل حقنة تاب بلوك على تسكين ألم الجرح بشكل كبير.</p><p>شكل حقنة تاب بلوك: إن إبرة تاب بلوك هي عبارة عن إبرة عادية تحتوي على مجموعة من المسكنات القوية التي توقف إشارات الألم الواصلة إلى البطن عند إعطائها للمريضة في منطقة عضلات البطن.</p><p>ما هي الخطوات المتبعة قبل إعطاء حقنة التاب بلوك؟ يشرح الطبيب للأم عمل حقنة تاب بلوك وفوائدها ويقوم بقياس الضغط والنبض. يتم تعقيم مكان الحقن ويتأكد الطبيب من عدم وجود حساسية لأي من مكونات الحقنة.</p><p>ما هي طريقة تخدير تاب بلوك؟</p><ul><li>يقوم طبيب التخدير بتخدير المريضة سواء تخدير كلي أو تخدير باستخدام حقنة الظهر وفقًا لحالتها الصحية.</li><li>في حالة حقنة الظهر تكون المريضة واعية بمراحل الولادة.</li><li>يقوم الدكتور أحمد مرزوق بعمل شق في منطقة أسفل البطن فوق العانة.</li><li>ثم يقوم بقطع عضلات البطن حتى يصل إلى الرحم.</li><li>يسحب الدكتور الطفل و يقص الحبل السري.</li><li>يخرج المشيمة من الرحم ويغلقه بغرز قابلة للذوبان.</li><li>يُحدد المنطقة المناسبة لحقن التاب بلوك بالاستعانة بجهاز الموجات فوق الصوتية.</li><li>تُوجَّه إبرة تاب بلوك بشكل عمودي  بين عضلات البطن حتى يصل طرف الإبرة إلى الفراغ فوق عضلة البطن المستعرضة.</li><li>يحرص على ألا تكون الإبرة داخل وعاء دموي.</li><li>يحقن محتويات الحقنة ببطء ثم يسحب الإبرة.</li></ul><p>ما هي مميزات الولادة بدون ألم باستخدام التاب بلوك؟</p><ul><li>تعمل حقنة التاب بلوك على تخفيف الألم  لمدة أطول بعد الولادة القيصرية حيث يستمر تأثيرها في عدم الإحساس بألم الجراحة لمدة تصل إلى 24 ساعة، وتمتد في أحيان كثيرة إلى 36 ساعة.</li><li>عدم وجود آثار جانبية شائعة نظرًا لعدم احتوائها على المواد الأفيونية التي تدخل في تكوين المسكنات الأخرى.</li></ul><p>أضرار إبرة تاب بلوك؟ من الممكن أن تسبب إبرة تاب بلوك ضررًا في حالة حقنها بطريقة خاطئة أو في مكان خاطئ، لذا يلزم حقنها على يد طبيب تخدير متمرس وصاحب خبرة كبيرة وهذا ما يوفره مركز دكتور أحمد مرزوق.</p><p>كما تعمل حقنة التاب بلوك على تسكين ألم الجرح الناتج عن العملية القيصرية فقط ولا تسكن ألم الرحم.</p><p>ما هو PCA؟ هو أحد التقنيات الحديثة في الولادة القيصرية بدون ألم حيث تحصل السيدة على جرعة من المسكنات القوية مثل المورفين، والفينتانيل والهيدرومورفين، من خلال توصيل جهاز PCA بوريد المريضة عن طريق أنبوب رفيع يتصل بكانيولا مثبتة في يد السيدة، وتستطيع السيدة بعده المشي والتحرك بدون ألم مما يقلل فرصة حدوث الجلطات بعد الولادة، ولكن من الممكن أن يتسبب في النعاس وبعض آلام المعدة والإمساك.</p><p>ما الفرق بين حقنة التاب بلوك والـ PCA؟ تختلف تقنية تاب بلوك عن الـ PCA، حيث إن التاب بلوك هو مخدر موضعي يتم حقنه في منطقة البطن لكي  يسكن الألم الناتج عن الجرح فقط، فتستطيع السيدة التحرك بعد العملية دون الشعور بألم الجرح لمدة تتراوح بين 24 ساعة وال 36 ساعة بينما يعمل جهاز الـ PCA على تسكين ألم الجرح وألم الرحم، إذ أن جهاز الـ PCA يحتوي على مجموعة من المسكنات القوية التي يتم تركيبها بواسطة كانيولا في وريد الأم بعد الولادة، والتي تفرز مجموعة من المسكنات بجرعات معينة عند الضغط على زرار الجهاز عند شعور الأم بالألم.</p><p>ويقرر الطبيب بالاتفاق مع المريضة الاختيار بين التاب بلوك والـ PCA حسب الحالة الصحية للمريضة ومدى إحساسها وتقبُّلها للألم، وهل تعاني من حساسية من أحد أنواع المسكنات، والتكلفة، ومقارنة المزايا والآثار الناتجة عن كلًا من الاختيارين.</p><p>ما هو سعر حقنة تاب بلوك في مصر؟ يختلف سعر الولادة القيصرية باستخدام التاب بلوك نتيجة عدة عوامل منها خبرة الطبيب والفريق المعاون له وخبرة طبيب التخدير وجودة المستشفى التي ستتم فيها العملية والأدوية المستخدمة والمتابعة بعد العملية.</p><p>إذا كنتِ ترغبين في ولادة بدون ألم تستطيعين التوجه لمركز دكتور أحمد مرزوق  استشاري جراحة النساء والتوليد وفريقه الطبي المعاون الذي تم تدريبه على أعلى مستوى وعلى أحدث التقنيات.</p>',NULL,NULL,'BlogPosting','الولادة بدون ألم تاب بلوك | د. أحمد مرزوق',NULL,'Dr Ahmed Marzouk Clinic',NULL)
